using Catalog.API.Models;
using MongoDB.Driver;

namespace Catalog.API.Data;

public static class CatalogInitialData
{
    public static async Task SeedAsync(IMongoCollection<Product> products)
    {
        var validIds = GetPreconfiguredProducts().Select(p => p.Id).ToHashSet();
        await products.DeleteManyAsync(p => !validIds.Contains(p.Id));

        foreach (var product in GetPreconfiguredProducts())
        {
            await products.ReplaceOneAsync(
                p => p.Id == product.Id,
                product,
                new ReplaceOptions { IsUpsert = true });
        }
    }

